style.css:
@-moz-document domain("sohu.com") {
/* ============================================================
     Palette
     base bg          #14181d
     elevated surface #1c2128
     header/footer    #0d1117
     border subtle    #262c33
     border component #2d333b
     text primary     #e6edf3
     text reading     #c8d0d9
     text muted       #8b949e
     link/accent      #5fb0e6 (hover #9bd4ff)
     brand orange     #ff7a45 (Sohu red-orange, tuned for dark)
     ============================================================ */

  :root {
    color-scheme: dark;
  }

  /* ---------- Base ---------- */
  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* Common page wrappers that carry a hardcoded white background */
  .article-page,
  .index,
  .main-content,
  .content,
  #main,
  .wrapper,
  .page,
  .container,
  .top-box-wrapper,
  .wrapper-box,
  .main-box,
  .box-wrapper {
    background-color: transparent !important;
  }

  /* classic-homepage / Sohu-video promo strip (light gradient art) */
  .swf-top,
  .swf-top a,
  .swf-banner {
    background-color: #1c2128 !important;
    background-image: none !important;
  }

  /* home center "点击进入·经典版首页" classic-homepage entry banner (#entrance):
     a single raster PNG with a cream background baked in (fox mascot + text +
     yellow "经典版首页" pill). Luminance-invert to dark; the hue-rotate preserves
     the fox red-orange + yellow-pill identity while flipping the cream to dark. */
  #entrance {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* home top-right compliance-badge carousel (#report .jubao-con): official
     report / supervision badges rendered as raster image links. Three frames
     ship a light background (网络监督专区 white, 网上有害信息举报专区 light-blue,
     社会主义核心价值观 cream) that glare on the dark page; the 学习强国 / 伟大的变革
     frames are already dark red and must stay untouched. Luminance-invert only
     the light frames — the hue-rotate keeps the red/blue emblem hues. */
  #report .jubao-con.jubao01,
  #report .jubao-con.jubao04,
  #report .jubao-con.jubao05 {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* light-grey filler tiles / plugin modules on the home grid */
  .content-other-item,
  .other-item,
  .grey-box,
  .gray-box,
  .title-cut,
  .picture-group,
  .author-subscribe-area,
  .fun-frag,
  .extend-mod,
  .other-modA,
  .other-modB,
  .plugin,
  .yule-play,
  .sports-match,
  .stock-tabs-c,
  .stock-box,
  .fun-list,
  .mod-box {
    background-color: #1c2128 !important;
  }

  /* Soften every light border into a subtle dark one */
  * {
    border-color: #262c33 !important;
  }

  /* The blanket reset above also paints the TRANSPARENT sides of Sohu's
     CSS-triangle carets (width:0;height:0 boxes), so every tooltip/dropdown
     arrow renders as a solid rectangle. `*` does not match pseudo-elements,
     so only these real-element triangles need restoring: clear all four
     sides, then repaint the single solid edge to match the surface it
     points at (#333 tooltips, our #1c2128 flyouts, the white QR panel). */
  .side-sohu-three,
  .side-feedback-three,
  .shh-three,
  .sohu-email-three,
  .more-list-arrow-icon,
  .BackTop .right-arrow,
  .wechat-qrcode .right-arrow,
  .leftarrow,
  .rightarrow,
  .leftdisable,
  .rightdisable,
  .icon-left-arrow,
  .icon-right-arrow,
  .tbl-masker,
  .trc_popover_arrow {
    border-color: transparent !important;
  }

  /* dark #333 tooltips (float toolbar, header 搜狐号 / 邮箱 flyouts) */
  .side-sohu-three,
  .side-feedback-three {
    border-left-color: #333 !important;
  }

  .shh-three,
  .sohu-email-three {
    border-top-color: #333 !important;
  }

  /* channel-nav "更多" dropdown: points up at our dark .navigation-more-list */
  .more-list-arrow-icon {
    border-bottom-color: #1c2128 !important;
  }

  /* the wechat QR flyout stays white (scannable), so its arrow stays white */
  .BackTop .right-arrow,
  .wechat-qrcode .right-arrow {
    border-left-color: #fff !important;
  }

  /* profile feed-tab scroll arrows: enabled follows the text color, disabled
     ships #ccc (a "muted on white" grey that glares on dark) */
  .leftarrow {
    border-right-color: #c4cdd6 !important;
  }

  .rightarrow {
    border-left-color: #c4cdd6 !important;
  }

  .leftdisable {
    border-right-color: #484f58 !important;
  }

  .rightdisable {
    border-left-color: #484f58 !important;
  }

  /* business.sohu.com hero-carousel arrows sit on top of the photo, so they
     keep their white fill (the .tbl-masker entries above are Taboola skeleton
     spacers that use a transparent border as padding, not a caret) */
  .icon-left-arrow {
    border-right-color: #fff !important;
  }

  .icon-right-arrow {
    border-left-color: #fff !important;
  }

  .trc_popover_arrow {
    border-bottom-color: #1c2128 !important;
  }

  /* home channel-section headers carry a 2px Sohu-gold top rule as a brand
     accent (paired with the short red channel tab): the big sections on
     .area[class*="content-"] (娱乐 / 体育 / 财经 / 汽车 …) and the smaller
     ones directly on .title-cut (时尚 / 教育 / 旅游 / 美食 …). The blanket
     border-color reset above flattened every one to grey, leaving the header
     half-styled. Restore the gold; width>0 only exists where the site drew it,
     so this paints nothing on the 0-width .title-cut header pills elsewhere. */
  .area[class*="content-"],
  .title-cut {
    border-top-color: #fbd300 !important;
  }

  /* ---------- Header / top nav ---------- */
  .sohu-head,
  header,
  .header,
  .area-header,
  .tbl-explore-more-site-header {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
  }

  .sohu-head a,
  header a,
  .header a,
  .sohu-head-box,
  .top-head,
  .head-item,
  .head-item a,
  .login,
  .login-area,
  .login-area a {
    color: #e6edf3 !important;
    background-color: transparent !important;
  }

  .sohu-head a:hover,
  header a:hover,
  .head-item a:hover {
    color: #9bd4ff !important;
  }

  .divide-line {
    background-color: #2d333b !important;
  }

  /* primary nav bar (channels) */
  .nav,
  .nav.area,
  .menu,
  .nav-list,
  .channel,
  .channel-list {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .nav a,
  .menu a,
  .channel a {
    color: #c4cdd6 !important;
  }

  .nav a:hover,
  .menu a:hover,
  .channel a:hover {
    color: #ff7a45 !important;
  }

  /* ---------- Search box ---------- */
  .search-input,
  input[type="text"],
  input[type="search"],
  input.text,
  .search input,
  textarea {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  .search-input::placeholder,
  input::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  .search-btn,
  .search button,
  button.search {
    background-color: #ff7a45 !important;
    color: #14181d !important;
    border-color: #ff7a45 !important;
  }

  /* ---------- Home aggregator grid ---------- */
  .main-left,
  .main-right,
  .left,
  .right,
  .scroll,
  .index-focus,
  .focus,
  .swiper-focus,
  .block,
  .news-box,
  .feed,
  .feed-list,
  .feed-content,
  .list,
  .card {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* section / block labels + hardcoded-dark headlines/metadata */
  .title,
  .block-title,
  .focus-title,
  .news-title,
  .titleW,
  .tab,
  .col-title,
  .other-title,
  .tt,
  .txt,
  .focus-t,
  .swf-tt,
  h2,
  h3 {
    color: #e6edf3 !important;
  }

  /* read counts / muted metadata that ship hardcoded grey */
  .read-num,
  .read-count,
  .num,
  .source-name,
  em.read-num {
    color: #8b949e !important;
  }

  /* headline links */
  a,
  .title a,
  .news-title a,
  .feed a,
  .list a {
    color: #c4cdd6 !important;
  }

  a:hover {
    color: #9bd4ff !important;
  }

  /* hot-list / ranking widgets */
  .rank,
  .ranklist,
  .hot,
  .news-rank,
  [class*="rank"],
  [class*="hot-list"] {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* thumbnails keep their own colors; just no white tile behind them */
  .pic,
  .img-do,
  .ad-focus,
  .thumb,
  .pic-box {
    background-color: transparent !important;
  }

  /* home right-column widget (e.g. "北京要闻"): each headline row is an
     a.shadow with a hardcoded rgb(249,249,249) pill bg — flatten it.
     The .qrcode stays white (it's a scannable QR code, like a logo). */
  a.shadow {
    background-color: transparent !important;
  }

  /* home sidebar "热门文章" rank list: rank #1 is a gold rgb(255,209,0) disc
     (.pic .sn, brand identity — untouched); ranks 2+ ship a bright
     rgb(235,235,235) disc with rgb(102,102,102) numerals that glare on the
     dark rail. Only the grey variant is darkened. */
  .hot-article .sn-list .list-item .sn {
    background-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  /* hairline dividers shipped as light BACKGROUNDS (not borders), so the
     blanket border-color reset never reaches them: the 北京城事 city panel
     rows (#eee), its tab separator (#e5e5e5), the stock widget's price/percent
     separator (#ccc), the profile card rules and the business hot-stock and
     hot-article separators (#ebebeb). */
  .other-divideline,
  .tabs-divideline,
  .stock-info .divider,
  .stock-info .s-line,
  .stock-c .divider,
  .row-line,
  .HotArticle .seperate,
  #hotstock .hot-title .label {
    background-color: #2d333b !important;
  }

  /* home search autocomplete (#suggestions): a 549x422 pure-white panel with
     near-black rows — it does not exist in the DOM until you type, so no
     load-time scan sees it. The bold <b> keyword highlight ships #f43640
     (3.7:1 once the panel is dark); lift it, keeping the red identity. */
  #suggestions {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  #suggestions .suggestion {
    color: #c4cdd6 !important;
  }

  #suggestions .suggestion:hover {
    background-color: #262c33 !important;
  }

  #suggestions .suggestion b {
    color: #f85149 !important;
  }

  /* home sidebar 赛事直播 schedule rows ship a white rgb(242,242,242) :hover
     that traps our lifted team names (light-on-light, ~1.05:1) */
  .sports-match .match:hover {
    background-color: #1c2128 !important;
  }

  /* home 快速找车 widget: opening 选品牌 / 选车型 drops a 394x348 white .selcon
     panel (with an #f7f7f7 "热门" strip) under our light text */
  .selcon,
  .selcon .rmode {
    background-color: #1c2128 !important;
  }

  .selcon .rmode {
    color: #8b949e !important;
  }

  /* home 楼市精选 widget: the "尽在焦点" kicker and the 帮你买房 form labels
     ship a hardcoded near-black rgb(25,25,25) — dark-on-dark */
  .focus-ad .atfocus-title,
  .focus-ad .key {
    color: #c4cdd6 !important;
  }

  /* home sidebar plugin tab bars (e.g. .sports-match 赛事直播 / 精彩回放):
     the selected tab ships a light-grey rgb(238,238,238) box + near-black
     text (light-on-light) and the idle tab ships near-black text
     (dark-on-dark). Give the pair a readable dark-theme treatment. */
  .head-tab .left-tab,
  .head-tab .right-tab,
  .plugin .left-tab,
  .plugin .right-tab,
  .sports-match .left-tab,
  .sports-match .right-tab {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .head-tab .activeTab,
  .plugin .activeTab,
  .sports-match .activeTab {
    background-color: #1c2128 !important;
    color: #ff7a45 !important;
  }

  /* home sports-match schedule rows (a.match): team names ship near-black
     rgb(17,17,17) and the date / round metadata ships dim rgb(102,102,102)
     — both dark-on-dark on the elevated widget. Lift names to primary and
     metadata to muted; the VS badge + team logos keep their own colors. */
  .sports-match .match .left-text,
  .sports-match .match .right-text,
  .match .match-content .left-text,
  .match .match-content .right-text {
    color: #e6edf3 !important;
  }

  .sports-match .match .match-head span,
  .sports-match .match .normal-text,
  .match .match-head span,
  .match .match-head .normal-text {
    color: #8b949e !important;
  }

  /* home real-estate promo widget (.focus-ad, 楼市精选 / 帮你买房): the
     container ships a light rgb(249,249,249) panel and the selected
     .ftab-nav-item ships an rgb(238,238,238) pill with near-black text. */
  .focus-ad {
    background-color: transparent !important;
  }

  .focus-ad .ftab-nav-item.active,
  .focus-ad .ftab-nav-item.active span {
    background-color: #1c2128 !important;
    color: #ff7a45 !important;
  }

  .focus-ad .ftab-nav-item span {
    color: #c4cdd6 !important;
  }

  /* home 快速找车 auto widget (.car-right-box): the 选品牌 / 选车型 select
     boxes ship white rgb(255,255,255) fields, and the car-category labels
     (SUV / MPV / 跑车 …) ship dim rgb(102,102,102) dark-on-dark */
  .car-right-box .selbox,
  .car-right-box .seltit {
    background-color: #1c2128 !important;
  }

  .car-right-box .auto-hot-model li a span,
  .car-right-box .car-tuijian span {
    color: #c4cdd6 !important;
  }

  /* home 搜狐号 subscribe card (.author-subscribe .container-box): each
     media-account source name ships near-black rgb(17,17,17) dark-on-dark */
  .author-subscribe .container-box .name,
  .container-box a.content-left .name {
    color: #c4cdd6 !important;
  }

  /* home stock widget selected tab uses li.active-bg with a white box */
  .stock-tabs-c .stock-header li.active-bg,
  li.active-bg {
    background-color: #1c2128 !important;
    color: #ff7a45 !important;
  }

  /* Stock up/down semantics. Chinese markets encode RED = up, GREEN = down —
     never invert or flatten these. Two separate faults: on the www home the
     native red rgb(209,27,36) only reaches 3.3:1 on our dark card, and on the
     #Index channel templates our own `#Index *` color rule (specificity 1,0,0)
     out-specifies the site's `.stock-tabs-c .content .red-txt` and repaints
     BOTH directions the same neutral grey — destroying the signal outright.
     Restore each direction at a luminance that reads on dark, hue preserved.
     The #Index-prefixed selectors are what beat `#Index *`. */
  /* Every descendant of a state block is natively the state colour (measured: the
     value, the caret, the delta and the separator all read rgb(2,156,89) inside
     .green-txt), so colour the whole subtree rather than an enumerated few — naming
     only .stock-num and .iconfont left `span.stock-r` grey. The #Index-prefixed arms
     are what out-specify our own `#Index *` rule, whose (1,0,0) beats a bare class. */
  .stock-info.red-txt,
  .stock-info.red-txt *,
  #Index .stock-info.red-txt,
  #Index .stock-info.red-txt * {
    color: #f85149 !important;
  }

  .stock-info.green-txt,
  .stock-info.green-txt *,
  #Index .stock-info.green-txt,
  #Index .stock-info.green-txt * {
    color: #3fb950 !important;
  }

  /* The 自选股 watchlist and hot-stock rows are SEPARATE components: the direction
     class rides on `.price` AND on `.rate` (`div.price.stock-red`, `div.rate.stock-red`).
     Keying on `.rate` alone left the price column flat, so a gain and a loss still read
     the same neutral grey in that column. Key on the direction class itself. */
  .stock-red,
  #Index .stock-red {
    color: #f85149 !important;
  }

  .stock-green,
  #Index .stock-green {
    color: #3fb950 !important;
  }

  /* footer license block (.service-info .license): one cert label
     (#internetPass) ships a dim rgb(64,64,64) — lift the whole block */
  .license,
  .license a,
  .license span,
  #internetPass {
    color: #c4cdd6 !important;
  }

  /* ---------- Article reader (the key surface) ---------- */
  #article-container,
  .article-page .main,
  .left.main,
  .text,
  .article-info {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* the long-form body — soft off-white, comfortable for reading */
  article,
  #mp-editor,
  .article,
  #mp-editor p,
  .article p,
  .text p,
  #mp-editor span,
  .article span,
  #mp-editor div,
  .article div,
  #mp-editor font,
  .article font,
  #mp-editor li,
  .article li {
    color: #c8d0d9 !important;
    background-color: transparent !important;
  }

  /* title */
  .article-page h1,
  #article-container h1,
  .article-title,
  h1 {
    color: #e6edf3 !important;
  }

  /* byline / date / source / author */
  .article-info,
  .article-info a,
  .time,
  .source,
  .author,
  .media-name,
  .user-info,
  .statement,
  .declare {
    color: #8b949e !important;
  }

  .article-info a:hover,
  .media-name a:hover {
    color: #9bd4ff !important;
  }

  /* blockquotes */
  #mp-editor blockquote,
  .article blockquote,
  blockquote {
    background-color: #1c2128 !important;
    border-left-color: #2d333b !important;
    color: #c8d0d9 !important;
  }

  /* in-body links + the "返回搜狐，查看更多" link */
  #mp-editor a,
  .article a,
  .text a,
  .backword,
  .show-all {
    color: #5fb0e6 !important;
  }

  #mp-editor a:hover,
  .article a:hover,
  .backword:hover {
    color: #9bd4ff !important;
  }

  /* code inside articles */
  #mp-editor pre,
  .article pre,
  #mp-editor code,
  .article code {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* ---------- Author card / sidebar widgets on the article page ---------- */
  .author-card-c,
  .author-card,
  .author-info,
  .author-subscribe,
  .godR,
  .hot-article,
  .hot-article.bord,
  .side-box,
  .sidebar-box {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  /* right-hand article sidebar wrapper */
  .right-side-abroad,
  .right-side,
  #right-side-bar,
  .area-side {
    background-color: transparent !important;
  }

  /* ---------- Article page redesign (mpfe template) ---------- */
  /* author profile card (#user-info) ships a hardcoded white panel;
     its stat labels (文章 / 总阅读) ship a dim rgb(102,102,102) */
  #user-info {
    background-color: #1c2128 !important;
  }

  #user-info .user-num li {
    color: #8b949e !important;
  }

  /* author card "查看TA的文章>" button ships a light rgb(249,249,249) pill */
  #user-info .user-more {
    background-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  /* right-rail "热门精选" image-card widget + its top gallery ship white */
  #topScrollPic,
  .hot-atlas,
  .hot-atlas .con,
  .hot-atlas ul {
    background-color: transparent !important;
  }

  /* left action column (#shareInteraction): each like/comment/favorite/share
     control is a rgb(248,248,248) rounded button holding a dark raster glyph,
     and the count/label under it ships near-black (dark-on-dark). Darken the
     button, flip the glyph light, and lift the labels. */
  #shareInteraction .icon,
  #shareInteraction .item,
  .share-interaction-c .icon,
  .share-interaction-c .item {
    background-color: #1c2128 !important;
  }

  #shareInteraction .icon .no-like-icon,
  #shareInteraction .icon .like-icon,
  #shareInteraction .icon .no-collection-icon,
  #shareInteraction .icon .collection-icon,
  #shareInteraction .icon .comment-icon,
  #shareInteraction .icon .share-icon,
  #shareInteraction .item > img {
    filter: invert(1) brightness(1.7) !important;
  }

  #shareInteraction .count,
  .share-interaction-c .count {
    color: #8b949e !important;
  }

  /* "扫码打开手机搜狐网" QR-scan caption ships near-black text */
  .phone-scan-c .text1,
  .phone-scan-c .text1 span,
  .phone-scan-c .border-font {
    color: #c4cdd6 !important;
  }

  /* "内容举报" report link ships a dim rgb(96,96,96) */
  #articleReport .report,
  #articleReport .report-c span {
    color: #8b949e !important;
  }

  /* "大家都在看" recommendation heading ships a near-black inner span */
  #articleAllsee .title,
  #articleAllsee .title span,
  .article-allsee .title,
  .article-allsee .title span {
    color: #e6edf3 !important;
  }

  /* lazy-image placeholders paint a white ::before behind the <img>
     (flashes white on slow/broken load in these article widgets, and on
     the main reading surface itself: article-body <img> in #mp-editor /
     .article paint a full-size white ::before box) */
  .img-do img::before,
  .img-do img::after,
  .allsee-image img::before,
  .allsee-image img::after,
  .allsee-item img::before,
  .allsee-item img::after,
  .hot-atlas img::before,
  .hot-atlas img::after,
  article#mp-editor img::before,
  article#mp-editor img::after,
  #mp-editor img::before,
  #mp-editor img::after,
  .article img::before,
  .article img::after {
    background-color: #1c2128 !important;
    color: #8b949e !important;
  }

  /* author / editor name keeps the Sohu red identity, lifted for dark */
  .editor-name,
  .username,
  .unlogin-text,
  .author-name {
    color: #ff6a5a !important;
  }

