  }

  /* search empty-state (.tab-right-blank-wrap, "抱歉，没有找到相关结果") ships a
     680x352 pure-white panel with a light-grey illustration + rgb(102,102,102)
     text — a big glaring white block whenever a tab has no results. Its sibling
     #new-list-loading ("正在加载中…") is the same white panel shown only during
     the fetch window. Darken both to the page base; the light illustration reads
     fine on dark. */
  /* The 作者专栏 tab ships the SAME panel under its own class names
     (.tabs-column / .tab-column-blank-wrap), which the -right selectors above never
     matched — that tab kept a full white empty state. Cover both families. */
  .tab-right-blank-wrap,
  .tab-column-blank-wrap,
  .tabs-column,
  #new-list-loading {
    background-color: #14181d !important;
  }

  .tab-right-blank-wrap p,
  .tab-right-blank-wrap span,
  .tab-column-blank-wrap p,
  .tab-column-blank-wrap span,
  #new-list-loading,
  #new-list-loading p {
    color: #8b949e !important;
  }

  /* the empty-state illustration (mushroom + "?") is a greyscale raster with a
     baked-in white background — luminance-invert it so the white flips dark and
     the grey line-art lifts, matching the darkened panel */
  .tab-right-blank-wrap > div,
  .tab-column-blank-wrap > div {
    filter: invert(1) !important;
  }

  /* topic cards without a photo fall back to a baked-in white Sohu-logo PNG
     shipped as a data: URI (real topics load an http photo, which must stay
     untouched) — invert only the placeholder, keeping the fox's red. */
  .topic-img img[src^="data:image/png"] {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* search 搜狐号 / 作者专栏 tabs (.tabs-right): switching off 综合 swaps the result
     list for a 680-wide rgb(244,244,244) panel holding a grid of pure-white
     rgb(255,255,255) media-account cards with rgb(64,64,64) names — the entire tab
     renders as one glaring white block. It only exists after the tab is clicked, so
     no load-time scan on the default tab sees it. The card carries the SAME class as
     the grid container that wraps it, so the descendant selector is what picks out
     the card alone and leaves the grid gutters on the page base. */
  .tabs-right {
    background-color: #14181d !important;
  }

  .tabs-right .tabs-right-cards .tabs-right-cards {
    background-color: #1c2128 !important;
  }

  .tabs-right-cards-title {
    color: #e6edf3 !important;
  }

  /* the per-card "栏目：资料 | 资讯" strip ships rgb(248,248,248) and the rule under
     the read counts ships rgb(219,219,219) */
  .tabs-right-cards-column {
    background-color: #262c33 !important;
  }

  .card-bottom-divideline {
    background-color: #2d333b !important;
  }

  .tabs-right-cards-desc,
  .tabs-right-cards-bottom,
  .tabs-right-cards-column,
  .cards-bottom-left,
  .cards-bottom-right {
    color: #8b949e !important;
  }

  /* hot-search right rail = elevated card; autocomplete = floating surface */
  .search-content-right,
  #suggest-list-wrap,
  #input-suggest-list-wrap,
  .input-suggest-list-wrap,
  .input-suggest-list-item,
  .input-base-list-item {
    background-color: #1c2128 !important;
  }

  /* search-box autocomplete suggestion rows ship near-black text */
  .input-suggest-list-item,
  .input-suggest-list-item a,
  .input-base-list-item {
    color: #c4cdd6 !important;
  }

  .input-suggest-list-item:hover,
  .input-base-list-item:hover {
    background-color: #262c33 !important;
  }

  /* result + hot-search headings; media-account suggestion titles */
  .cards-content-title,
  .cards-content-title a,
  .cards-content-right-title,
  .cards-content-right-title a,
  .search-content-right-title,
  .section-item-right-title,
  .section-item-right-title a,
  .hotSearchList-item-text,
  .hotSearchList-item-text a {
    color: #e6edf3 !important;
  }

  /* result snippets, sources, search tabs, "查看全部" */
  .cards-content-right-desc,
  .cards-content-right-desc a,
  .cards-content-right-comm,
  .section-item-right-desc,
  .search-content-left-nav .nav-item,
  #nav-left > p,
  #nav-right > p,
  #nav-column > p,
  #find-all,
  #suggest-list-wrap a {
    color: #c4cdd6 !important;
  }

  /* Active search tab. The site marks it `.nav-item-active` (not `.active`),
     so the two selectors this theme used to carry were dead: the selected tab
     rendered pixel-identical to the unselected ones. Worse, the tab's own
     indicators were both erased by us — its rgb(240,29,29) label by the
     `#nav-left > p` rule above (1,0,1) and its 2px red underline by the
     blanket `* { border-color }`. The ids are what out-specify our own rule. */
  #nav-left.nav-item-active > p,
  #nav-right.nav-item-active > p,
  #nav-column.nav-item-active > p {
    color: #ff6a5a !important;
    border-bottom-color: #ff6a5a !important;
  }

  /* ============================================================
     Author / media profile (mp.sohu.com /profile) — the feed
     filter-tab bar (最新 / 动态 / 育儿 …) ships a white rank bar
     with a white active-tab box.
     ============================================================ */
  .tpl-rank-bar,
  .tap-rank-tap,
  .outtap,
  .leftpart,
  .rightpart {
    background-color: transparent !important;
  }

  .active_tap {
    background-color: #1c2128 !important;
  }

  .active_text {
    color: #ff7a45 !important;
  }

  .default_text,
  .inner_tap,
  .tap-rank-tap .tap-item {
    color: #c4cdd6 !important;
  }

  /* the tab-strip scroll arrows sit in 24px buttons with an rgb(235,235,235)
     :hover; the share row's circular buttons ship white rgb(255,255,255) /
     rgb(248,248,248) discs, and the copy-link one holds a dark raster glyph */
  .leftpart .leftout:hover,
  .rightpart .rightout:hover {
    background-color: #262c33 !important;
  }

  .share-wrapper .share-icon {
    background-color: #262c33 !important;
  }

  .share-wrapper .share-icon.share-copy img {
    filter: invert(1) brightness(1.7) !important;
  }

  /* mp.sohu.com legacy shell (error / 404 / notice pages): the header band and
     the whole content panel ship a literal white background. The header's
     4px rgb(251,211,0) bottom rule is brand identity — the blanket
     border-color reset flattens it, so restore it explicitly. */
  body > .module-header,
  body > .module-main {
    background-color: #14181d !important;
  }

  body > .module-header {
    border-bottom-color: #fbd300 !important;
  }

  body > .module-header,
  body > .module-header a,
  body > .module-main .right .tip {
    color: #c4cdd6 !important;
  }

  body > .module-main .right .tip {
    color: #8b949e !important;
  }

  /* the 404 headline keeps its Sohu gold, and the "打不开" bottle illustration
     is a raster with a cream background baked in — luminance-invert it while
     the hue-rotate preserves the orange line art */
  body > .module-main .right p:first-child {
    color: #fec744 !important;
  }

  body > .module-main .left img {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* ---------- Footer ---------- */
  .footer,
  #footer,
  .footer.area,
  .copyright,
  .area-footer {
    background-color: #0d1117 !important;
    color: #8b949e !important;
  }

  .footer a,
  #footer a,
  .copyright a {
    color: #8b949e !important;
  }

  .footer a:hover,
  #footer a:hover {
    color: #c4cdd6 !important;
  }

  /* ---------- Brand accent ---------- */
  /* Sohu uses a red-orange identity; keep the hue, tune for dark */
  .backword,
  .logo-text,
  .more-link {
    color: #ff7a45 !important;
  }

  /* "返回搜狐，查看更多" end-of-article CTA is a span.backword (+ fox icon
     i.backsohu) nested in #mp-editor > a, so our own `.article span` body rule
     (0,2,0) out-specified the bare `.backword` (0,1,0) and flattened the whole
     link — text and icon — to reading grey. Restore the Sohu brand orange with
     a selector that clears the body rule in both the #mp-editor and .article
     templates. */
  #mp-editor .backword,
  #mp-editor .backword i,
  .article .backword,
  .article .backword i {
    color: #ff7a45 !important;
  }

  ::selection {
    background-color: #ff7a45 !important;
    color: #14181d !important;
  }
}
